/* FisixOS boot logo for the bootloader, 2026-10-30.
 * Asher's white logo, downscaled 499x499 -> 400x400 Lanczos,
 * real editor, no AI. Same pixels as the JSON file in
 * your_files/fisixos-boot-logo-400x400.json, but compiled
 * in as a C array: a freestanding EFI bootloader has no
 * JSON parser, and parsing 160k numbers at boot would be
 * slower and riskier than drawing the array directly.
 * Windows does the same idea with a BMP in bootmgfw:
 * pixel data in the boot binary, drawn to GOP, then cleared. */
